/* Intermediate11 — data protection, protection metadata and honest detection boundaries. */
(function () {
  const N=AG.aws.n, clone=x=>JSON.parse(JSON.stringify(x));
  const canonical=(x,key='')=>{if(['Action','Resource','AWS'].includes(key)&&(typeof x==='string'||Array.isArray(x)&&x.every(v=>typeof v==='string')))return (Array.isArray(x)?x:[x]).slice().sort();if(Array.isArray(x)){const rows=x.map(v=>canonical(v));if(rows.every(v=>v&&typeof v==='object'&&typeof v.Sid==='string'))rows.sort((a,b)=>a.Sid.localeCompare(b.Sid));else if(rows.every(v=>v&&typeof v==='object'&&Number.isInteger(v.Priority)))rows.sort((a,b)=>a.Priority-b.Priority);return rows;}if(x&&typeof x==='object')return Object.fromEntries(Object.keys(x).sort().map(k=>[k,canonical(x[k],k)]));return x;};
  const same=(a,b)=>JSON.stringify(canonical(a))===JSON.stringify(canonical(b));
  const R='us-east-1', A='123456789012', ROOT=`arn:aws:iam::${A}:root`, REVIEW=`arn:aws:iam::${A}:role/security-reviewer`;
  const ID='00000000-0000-4000-8000-000000000001', KEY=`arn:aws:kms:${R}:${A}:key/${ID}`, OLD='invoice-archive-key', OLDARN=`arn:aws:kms:${R}:${A}:key/${OLD}`;
  const ALB=`arn:aws:elasticloadbalancing:${R}:${A}:loadbalancer/app/shop-alb/000001`, ACLID='00000000-0000-4000-9000-000000000001', ACL=`arn:aws:wafv2:${R}:${A}:regional/webacl/shop-login/${ACLID}`;
  const ROTATOR=`arn:aws:lambda:${R}:${A}:function:db-secret-rotator`, SECRET='shop/db', PARAM='/shop/payment-token';
  const Q=(q,correct,wrong,answer,explain)=>{const choices=wrong.slice();choices.splice(answer,0,correct);return {q,choices,answer,explain};};
  const admin={Sid:'PreserveAdministration',Effect:'Allow',Principal:{AWS:ROOT},Action:'kms:*',Resource:'*'};
  const keyPolicy={Version:'2012-10-17',Statement:[admin,{Sid:'InvoiceReader',Effect:'Allow',Principal:{AWS:REVIEW},Action:'kms:Decrypt',Resource:'*',Condition:{StringEquals:{'kms:EncryptionContext:tenant':'shopkaro'}}}]};
  const vis={SampledRequestsEnabled:true,CloudWatchMetricsEnabled:true,MetricName:'shop-login'};
  const rules=[{Name:'Common',Priority:0,Statement:{ManagedRuleGroupStatement:{VendorName:'AWS',Name:'AWSManagedRulesCommonRuleSet'}},OverrideAction:{None:{}},VisibilityConfig:vis},{Name:'LoginRate',Priority:1,Statement:{RateBasedStatement:{Limit:100,EvaluationWindowSec:60,AggregateKeyType:'IP',ScopeDownStatement:{ByteMatchStatement:{SearchString:'/login',FieldToMatch:{UriPath:{}},TextTransformations:[{Priority:0,Type:'NONE'}],PositionalConstraint:'EXACTLY'}}}},Action:{Block:{}},VisibilityConfig:vis}];
  const enc={Rules:[{ApplyServerSideEncryptionByDefault:{SSEAlgorithm:'aws:kms',KMSMasterKeyID:KEY},BucketKeyEnabled:true}]};
  const value='{"username":"test_app","password":"TEST_ONLY_lab_password"}';
  const files={};
  for(const [name,content,desc] of [['key-policy.json',keyPolicy,'Review kiya admin + context tak scoped reviewer decrypt'],['encryption.json',enc,'Aage ki writes ke liye default SSE-KMS; purani files apni purani encryption rakhti hain'],['waf-rules.json',rules,'Review kiya CommonRuleSet aur exact /login IP rate rule'],['visibility.json',vis,'Metrics aur sampled requests on'],['rotation.json',{AutomaticallyAfterDays:30},'Sirf rotation schedule ka config; function ka runtime check nahi hua']])files[name]={desc,content:JSON.stringify(content,null,2)};
  files['secret.json']={desc:'Sirf nakli training secret; asli credential kabhi mat chipkao',content:value};
  files['invoice-cipher.bin']={desc:'Local TEST ciphertext ka band dabba (handle); asli KMS wire bytes nahi',content:'LOCAL-ARCHIVE-INVOICE'};
  function seed(interview=false){return {region:R,securityScope:true,callerIdentity:{Account:A,Arn:interview?REVIEW:ROOT,UserId:'TRAINING'},kmsKeys:[{id:OLD,arn:OLDARN,fixtureId:'original-archive-key',state:interview?'Disabled':'Enabled',revision:1,policy:{Version:'2012-10-17',Statement:[{...admin,Action:['kms:DescribeKey','kms:PutKeyPolicy','kms:EnableKey']}]}}],kmsAliases:[],kmsCiphertexts:[{token:'LOCAL-ARCHIVE-INVOICE',keyId:OLD,context:{tenant:'shopkaro',purpose:'invoice'},plaintext:'TEST invoice101 INR2500'}],buckets:[{name:'shop-invoices',bucketId:'original-invoices',region:R,encryption:true,public:false,objects:[{key:'existing.txt',body:'TEST old invoice',size:16,serverSideEncryption:'AES256',etag:'"original"'}]}],secrets:[],parameters:[],webAcls:[],elbs:[{id:ALB,arn:ALB,name:'shop-alb',fixtureId:'original-alb',type:'application',scheme:'internet-facing',state:'active'}],lambdas:[{name:'db-secret-rotator',fixtureId:'reviewed-rotation-function',runtime:'python3.12',handler:'app.handler',state:'Active',memory:512,timeout:30}],detectors:[{id:'detector-shop',enabled:true,findings:[{Id:'training-exfiltration',Type:'UnauthorizedAccess:IAMUser/InstanceCredentialExfiltration.OutsideAWS',Severity:8,Title:'TRAINING: instance credentials AWS ke bahar use hue',Description:'Lesson ke liye pehle se daala fixture; asli pakda gaya event nahi'}]}]};}
  const mainSolution=[
    'aws kms create-key --description shop-invoices --policy file://key-policy.json',
    `aws kms create-alias --alias-name alias/shop-invoices --target-key-id ${ID}`,
    `aws kms enable-key-rotation --key-id ${ID} --rotation-period-in-days 180`,
    'aws s3api put-bucket-encryption --bucket shop-invoices --server-side-encryption-configuration file://encryption.json',
    `aws secretsmanager create-secret --name ${SECRET} --kms-key-id ${KEY} --secret-string file://secret.json`,
    `aws secretsmanager rotate-secret --secret-id ${SECRET} --rotation-lambda-arn ${ROTATOR} --rotation-rules file://rotation.json --no-rotate-immediately`,
    `aws secretsmanager get-secret-value --secret-id ${SECRET}`,
    `aws ssm put-parameter --name ${PARAM} --type SecureString --key-id ${KEY} --value TEST_ONLY_api_token`,
    `aws ssm get-parameter --name ${PARAM} --with-decryption`,
    'aws wafv2 create-web-acl --name shop-login --scope REGIONAL --cli-binary-format raw-in-base64-out --default-action \'{"Allow":{}}\' --rules file://waf-rules.json --visibility-config file://visibility.json',
    `aws wafv2 associate-web-acl --web-acl-arn ${ACL} --resource-arn ${ALB}`,
    `aws wafv2 get-web-acl-for-resource --resource-arn ${ALB}`
  ];
  const original=s=>{const a=s.account,k=a.kmsKeys.find(k=>k.id===OLD),b=a.buckets.find(b=>b.name==='shop-invoices'),lb=a.elbs.find(l=>l.id===ALB);return !!k&&k.fixtureId==='original-archive-key'&&k.state==='Enabled'&&!!b&&b.bucketId==='original-invoices'&&!b.public&&b.objects.length===1&&b.objects[0].body==='TEST old invoice'&&b.objects[0].serverSideEncryption==='AES256'&&lb?.fixtureId==='original-alb'&&a.lambdas.some(f=>f.fixtureId==='reviewed-rotation-function'&&f.name==='db-secret-rotator');};
  const tasks=[
    {text:'Purane invoices, archive key, ALB aur review kiya rotation function bache rahe',check:original},
    {text:'Enabled customer key: review ki hui policy, alias aur 180 din ka rotation',check:s=>{const k=s.account.kmsKeys.find(k=>k.id===ID);return !!k&&k.state==='Enabled'&&same(k.policy,keyPolicy)&&k.rotation?.period===180&&s.account.kmsKeys.length===2&&s.account.kmsAliases.some(a=>a.name==='alias/shop-invoices'&&a.keyId===ID);}},
    {text:'Aage ki writes ka bucket default nayi key/Bucket Key use karta hai; purani file waisi hi rahi',check:s=>{const b=s.account.buckets.find(b=>b.name==='shop-invoices');return b?.encryption==='kms'&&b.kmsKey===KEY&&b.bucketKey===true;}},
    {text:'Aaj ka TEST secret padha ja sakta hai; sirf 30 din ka rotation CONFIG; runtime check nahi hua',check:s=>{const v=s.account.secrets.find(v=>v.name===SECRET&&!v.deleted),k=s.account.kmsKeys.find(k=>k.id===ID);return !!v&&!!k&&k.state==='Enabled'&&v.keyId===KEY&&v.rotation?.lambdaArn===ROTATOR&&v.rotation.rules.AutomaticallyAfterDays===30&&v.rotation.runtime==='UNVERIFIED'&&v.versions.some(x=>x.value===value&&x.stages.includes('AWSCURRENT')&&(s.account.securityReads||[]).some(r=>r.kind==='secretValue'&&r.arn===v.arn&&r.versionId===x.id&&r.revision===v.revision&&r.value===value));}},
    {text:'Alag SecureString TEST token nayi key use karta hai; decrypt hua current version padha',check:s=>{const p=s.account.parameters.find(p=>p.name===PARAM);return p?.type==='SecureString'&&p.keyId===KEY&&p.value==='TEST_ONLY_api_token'&&(s.account.securityReads||[]).some(r=>r.kind==='parameter'&&r.name===PARAM&&r.version===p.version&&r.value===p.value);}},
    {text:'Review kiya, laagu karne wala WAF metadata purane ALB se juda, phir aaj ka association padha',check:s=>{const a=s.account.webAcls.find(a=>a.arn===ACL);return !!a&&a.scope==='REGIONAL'&&same(a.defaultAction,{Allow:{}})&&same(a.rules,rules)&&same(a.visibility,vis)&&s.account.elbs.find(l=>l.id===ALB)?.webAclArn===ACL&&(s.account.securityReads||[]).some(r=>r.kind==='wafAssociation'&&r.resource===ALB&&r.aclId===a.id&&r.revision===a.revision);}}
  ];
  const interviewSolution=[`aws kms enable-key --key-id ${OLD}`,`aws kms put-key-policy --key-id ${OLD} --policy-name default --policy file://key-policy.json`,'aws kms decrypt --key-id '+OLD+' --ciphertext-blob fileb://invoice-cipher.bin --encryption-context \'{"tenant":"shopkaro","purpose":"invoice"}\''];
  const itasks=[{text:'Purani archive key on; purana band (opaque) invoice bacha',check:s=>s.account.kmsKeys.length===1&&s.account.kmsKeys[0].fixtureId==='original-archive-key'&&s.account.kmsKeys[0].state==='Enabled'&&s.account.kmsCiphertexts.length===1&&s.account.kmsCiphertexts[0].plaintext==='TEST invoice101 INR2500'},{text:'Review ki hui key policy wapas, exact tenant tak scoped reviewer decrypt ke saath',check:s=>same(s.account.kmsKeys[0]?.policy,keyPolicy)},{text:'Asli matching purana TEST ciphertext aaj ki key revision par decrypt hua',check:s=>{const k=s.account.kmsKeys[0];return !!k&&k.state==='Enabled'&&AG.securityKeyAllowed(s.account,k,'kms:Decrypt',{tenant:'shopkaro',purpose:'invoice'})&&(s.account.securityReads||[]).some(r=>r.kind==='decrypt'&&r.token==='LOCAL-ARCHIVE-INVOICE'&&r.keyId===OLD&&r.revision===k.revision&&r.plaintext==='TEST invoice101 INR2500');}}];
  const cost=k=>{const baseline=k.objects*1000000*(1+k.reads),fraction=[0,.5,.9,.99][k.reuse],calls=k.bucket?Math.ceil(baseline*(1-fraction)):baseline,key=1+Math.min(k.rotations,2);return {baseline,calls,before:key+baseline*.03/10000,after:key+calls*.03/10000,key};};
  AG.registerLevels('intermediate',[{
    id:'security',icon:'🛡️',title:'Security: data, edge aur saboot',badge:'Security Senapati',
    objectives:['KMS policy/context/rotation aur envelope encryption debug karna','Secret ki value, backend credential aur rotation config alag-alag check karna','WAF protection ka metadata aur asli traffic ka saboot alag pehchanna','Detection services chun kar nazar wala response plan banana'],
    hook:{when:'ShopKaro course ki kahani (fictional)',title:'Mahasale se pehle chaar security tickets',text:'ShopKaro ke login par 50,000 requests/minute aa rahi hain. Ravi ka DB password chat mein mil gaya. Ek EC2 mining-pool domain se baat kar raha hai. Auditor poochta hai: invoices kaun decrypt kar sakta hai? Neha ko services ki list nahi chahiye; har risk ka owner aur saboot chahiye.',mission:'Pehle defense ka naksha dekho. Phir key/secret/WAF ka config theek karo aur asli state padho. Course ke fixtures fictional hain; Capital One ka sourced case alag label ke saath hai.'},
    steps:[
      {q:'Firewall, encryption aur detection ek hi problem kyun solve nahi karte?',analogy:'Dukaan ka guard bheed sambhalta hai, locker cash bachata hai, CCTV saboot deta hai. CCTV ki recording locker ki kho gayi chaabi theek nahi karti.',body:'<p>Threat ko actor/action/resource mein likho. Edge par WAF supported HTTP entry points check karta hai; SG/NACL network ke raaste control karte hain; IAM permissions tay karta hai; KMS key ke use ki permission deta hai. Detection ko owner, alert ka raasta aur response runbook chahiye.</p>',points:['Galti jo sab karte hain: GuardDuty ki finding ko roka hua attack samajhna. Detection ke baad rokna (containment), saboot bachana, credential cancel karna aur check karna, sab kisi ko saunpo.','Production mein aisa hota hai: seedha origin ka raasta CDN ke bachav ko bypass kar sakta hai; chauda IAM role encrypted data padh sakta hai. Har layer ka coverage aur bypass ka raasta review karo.','Hands-on: agle dry run mein IP traffic aur key ki permission alag panels mein follow karo. Expected: WAF action HTTP ka handling badalta hai, kms:Decrypt ki permission nahi.'],asli:'Woh control chuno jo dikhe hue risk ko sambhale; bacha hua risk aur naapa ja sakne wala saboot review karo.'},
      {q:'Kya KMS se 7,000-byte invoice seedha encrypt karenge?',analogy:'Bada parcel locker mein rakho. Parcel ki chaabi chhoti hai; master locker sirf parcel ki chaabi bachata hai.',body:'<p>Symmetric KMS Encrypt 4,096 bytes tak sambhalta hai. GenerateDataKey plaintext data key + lapeti hui (wrapped) ciphertext key deta hai. App payload ko local mein encrypt karti hai; ciphertext, nonce, wrapped key aur context save karti hai; phir plaintext key ko aam use se hata deti hai. Decrypt mein pehle key khulti hai, phir payload check hokar decrypt hota hai.</p>',points:['EncryptionContext secret nahi, case-sensitive, check hone wala metadata hai. Encrypt/Decrypt ko bilkul same context chahiye; context logs mein dikh sakta hai, isliye password/PII mat daalo.','AWS owned keys service sambhalti hai; AWS managed keys account mein dikhti hain par unki policy badal nahi sakte; customer managed keys policy/grants/lifecycle ka control aur kharcha deti hain. Dedicated HSM/PKCS#11 ki zaroorat ho toh CloudHSM sahi ho sakta hai. Client-side encryption badal deti hai ki plaintext kahan khulta hai.','Kaam: lab19 ex1 laptop par asli AES-GCM roundtrip aur chhed-chhaad (tamper) wali failure chalata hai. App ke band handles sirf key/context/access ki state ka model hain; handles khud encryption nahi.'],code:'aws kms generate-data-key --key-id alias/shop-invoices --key-spec AES_256 --encryption-context \'{"tenant":"shopkaro"}\'',asli:'Production mein review kiya encryption SDK/format use karo; yeh toy envelope safe memory handling aur key recovery nahi karta.'},
      {q:'S3 read allowed hai; phir KMS AccessDenied kyun?',analogy:'Invoice room ka gate pass aur locker ka access, do alag manzooriyan hain. Gate pass se locker ki permission nahi milti.',body:'<p>SSE-KMS reads ko S3 ki permission aur ek chalne layak KMS key chahiye, jahan key policy/IAM/grant ka koi lagu raasta ho. Explicit Deny Allow ko hara sakta hai. Root account ko key policy ka delegation IAM permissions chalu karta hai; principal ko seedha Allow ek alag raasta hai. Cross-account use mein dono taraf sahi permissions chahiye.</p>',points:['Customer managed symmetric AWS_KMS ka automatic rotation khud on karna padta hai; 90–2,560 din set ho sakta hai, default 365 din. AWS managed keys har saal rotate hoti hain. Imported symmetric material eligible on-demand rotation support karta hai; asymmetric/HMAC/custom-store ke niyam alag. Rotation se key ID aur purana decrypt material bacha rehta hai; purana data dobara nahi likha jaata.','Naya default SSE-KMS/BucketKeyEnabled sirf aage ki writes par lagta hai. Purani files ke liye soch kar migration karni padti hai. Bucket Keys calls ko 99% tak kam kar sakti hain, requesters/workload par depend; cache se hua use har file read par ek KMS audit event nahi banata, na har request par key policy turant dobara check hoti hai.','Kaam: GetBucketEncryption ko purani HeadObject se compare karo. Interview alag se ek pehle se bani disabled key, chhoti policy aur exact context wapas laata hai; nayi key purana ciphertext decrypt nahi kar sakti.'],code:'aws kms enable-key-rotation --key-id '+ID+' --rotation-period-in-days 180',asli:'Delete karna rotation se alag hai. ScheduleKeyDeletion 7–30 din wait karta hai; cancel karne par key Disabled rehti hai. Enable/delete se pehle dependencies aur recovery review karo.'},
      {q:'Secret save karna aur credential rotate karna alag kyun hain?',analogy:'Office ke naye taale ki chaabi register mein likhna kaafi nahi. Taala badalna, nayi chaabi test karna aur staff ki chaabi refresh karna, sab saath karna padta hai.',body:'<p>Secrets Manager secret versions/rotation/replication ke liye hi bana hai. Parameter Store config ke liye kaam ka hai: SecureString KMS se encrypt karta hai, par credential rotation khud nahi deta. Standard parameter ka size 4 KiB, Advanced 8 KiB; storage/throughput/KMS ka kharcha chune features par depend karta hai.</p>',points:['Lambda rotation ka pattern: createSecret → asli backend mein setSecret → testSecret → finishSecret se stage promotion. AWSPENDING chalne wala AWSCURRENT nahi hai. App ke caches ka refresh limit mein ho aur rotation ke baad recovery ho; asli secret values kabhi log mat karo.','RotationEnabled sirf config batata hai, password ka safal badalna nahi. --no-rotate-immediately ke saath bhi AWS testSecret chalata hai. Native managed service/external-secret integrations ka apna setup hai; "har password apne aap 30 din mein" jaisa koi niyam nahi.','Kaam: secret.json (TEST_ONLY) dekho, aaj ki value save/padho, phir lab19 ex3 pending/current labels ko ek TEST backend dict se compare karta hai. Docker/asli DB/Lambda rotation check nahi hua.'],code:'aws secretsmanager get-secret-value --secret-id shop/db\naws ssm get-parameter --name /shop/payment-token --with-decryption',asli:'Lagbhag US East: Secrets Manager $0.40/secret/mahina + $0.05 har 10000 API calls; rotation Lambda/KMS/replicas kharcha jod sakte hain. Parameter Store ki notification policy backend credential rotate nahi karti.'},
      {q:'TLS certificate ka Region aur renewal ka owner kaun?',analogy:'Dukaan ka license manzoor hona aur har branch par nayi copy lagna, alag kaam hain.',body:'<p>ACM ke non-exportable public certificates integrated AWS services ke saath free hain; supported exportable public/ACME aur Private CA ke options ka alag bill hai. ACM eligible renewal sambhalta hai, par DNS/email validation aur deployment ki shartein maayne rakhti hain.</p>',points:['ALB apne Region ka certificate use karta hai. CloudFront ka viewer certificate ACM us-east-1 se aata hai. API Gateway ke certificate ka Region endpoint type par depend karta hai; exact integration dekho.','Exportable certificates integrated services ke bahar bhi chal sakte hain, par renew hua certificate/key operator ko khud lagana padta hai. "ACM public certificates kabhi export nahi hote" mat sikhao.','Kaam: certificate ka Region chunne se pehle batao ki TLS kahan khatam hota hai. Production check: hostname/SAN, chain, expiry, renewal ki eligibility aur laga hua serial.'],asli:'Certificate ki safal request sirf config ka saboot hai; chalta TLS endpoint aur renewal/deployment ki monitoring check karo.'},
      {q:'100 requests/60 s wala WAF rule har login bot rok deta hai?',analogy:'Guard ek line ki bheed ginta hai. 10000 alag lines mein thodi-thodi bheed ek line ki limit ke neeche reh sakti hai.',body:'<p>WAF web ACLs supported HTTP resources par lagte hain. Managed rule groups jaane-pehchaane patterns pakadne mein madad karte hain; rate rules matching traffic ko 60/120/300/600 s windows mein ginte hain (default 300). Kam se kam limit 10. Rate ka andaaza aur lagne mein lagne wala time, isliye threshold exact API quota nahi.</p>',points:['Rule ki priority aur rokne wale actions maayne rakhte hain. Pehle Count se dekho, sahi traffic aur galat blocks check karo, phir review karke Block/Challenge/CAPTCHA. Is mission mein CommonRuleSet OverrideAction None aur /login rate Action Block hi laagu karne wala metadata hai.','Bikhre bots, shared NAT ke users, bharose wale proxy IP headers, credential-stuffing accounts aur origin bypass ka alag analysis chahiye. Bot Control/ATP, account controls/MFA aur app ke query/input fixes WAF ke saath kaam aate hain; SQLi se bachav ke liye parameterized queries bhi chahiye.','Shield Standard basic DDoS protection deta hai; Advanced paid features aur shartein poori hone par eligible protection/response jodta hai. Subscription lagbhag $3,000/mahina, kam se kam ek saal ki commitment; protected resources ka data transfer aur premium features kharcha jod sakte hain. Advanced resource/config review ke bina apne aap refund ya poore account ki protection nahi. Firewall Manager accounts mein supported policies ek jagah se chalata hai.','Kaam: lab19 ek Regional ACL/ALB association banata hai aur purana LockToken reject karta hai. Moto ya app ka config model koi HTTP filtering ya bot rokna nahi naapta.'],asli:'Asli entry ka raasta bachao. CloudFront us-east-1 mein CLOUDFRONT scope use karta hai; ALB usi Region ka REGIONAL scope. Advanced khareedne se pehle aaj ke daam/commitments dekho.'},
      {q:'Finding, vulnerability, PII aur compliance ka saboot kis service se?',analogy:'CCTV shaq wala behaviour dikhata hai, building ki jaanch kamzor taale dikhati hai, records ka audit sensitive files pehchanta hai.',body:'<div class="tbl-wrap"><table class="security-table"><tr><th>Zaroorat</th><th>Option / limit</th></tr><tr><td>Threat ke signals</td><td>GuardDuty; plan/Region/resource coverage review karo</td></tr><tr><td>Software ki kamzori</td><td>Inspector; supported EC2/ECR/Lambda coverage</td></tr><tr><td>S3 ka sensitive data</td><td>Macie; dhoondhne ka scope, data chhupana nahi</td></tr><tr><td>Resource compliance</td><td>Config rules; theek karna alag kaam</td></tr><tr><td>Security posture/findings</td><td>Security Hub; on kiye integrations aur controls</td></tr><tr><td>Jaanch ke rishte</td><td>Detective; supported data/coverage</td></tr><tr><td>API ka saboot</td><td>CloudTrail; management/data events ka scope maayne rakhta hai</td></tr></table></div>',points:['GuardDuty ka basic analysis supported CloudTrail management/flow/DNS data streams se chalta hai. Optional plans mein S3, EKS/RDS, Lambda, malware, runtime aur AI wala coverage aata hai; features/billing/availability alag hain. Runtime Monitoring security agent use karta hai, isliye "GuardDuty kabhi agent use nahi karta" galat hai.','Kaam: detector-shop/training-exfiltration ke liye list-detectors → get-findings. Expected: pehle se daali TRAINING finding, asli event nahi. Incident ka owner tay karo; affected workload/credentials roko, saboot bachao, scope ki jaanch karo aur recovery check karo.','Production mein aisa hota hai: alerts ki thakaan, unsupported/uncovered workloads aur response ka owner na hona findings ko latkaaye rakhta hai. KMS encryption chori hue par allowed role ko data padhne se nahi rokta.'],asli:'Detection ka bharosa/coverage aur response ka time naapna padta hai. Detector on karna yeh prove nahi karta ki breach ruk jaata.'},
      {q:'Customer login aur employees ka AWS access kaise alag karein?',analogy:'Customers ka shopping account aur employees ka warehouse master access, do alag identity systems hain.',body:'<p>Cognito user pools app ka sign-up/sign-in/JWTs sambhalte hain; identity pools supported identities ko scoped temporary AWS credentials mein badalte hain. IAM Identity Center employees ka access sambhalta hai; workload ke IAM roles EC2/Lambda/ECS ke liye hain. Tokens ka issuer/audience/expiry check aur sahi API permission phir bhi chahiye.</p><p><b>Sourced incident: Capital One 2019.</b> <a href="https://www.justice.gov/usao-wdwa/united-states-v-paige-thompson" target="_blank" rel="noopener noreferrer">DOJ batata hai</a> ki hacker ek galat set kiye web application firewall ke raaste hui. <a href="https://www.capitalone.com/digital/facts2019/" target="_blank" rel="noopener noreferrer">Capital One ke mutabik</a> lagbhag 10 crore US aur 60 lakh Canada ke logon par asar pada. Yeh case SSRF/metadata se bachav aur sabse kam permission ke review ki wajah deta hai; lesson yeh daava nahi karta ki koi ek missing service is incident ko pakka rok deti.</p>',points:['IMDSv2 ka token wala metadata access SSRF ka khatra kam karta hai; supported instance settings zaroori karo aur role ki pahunch review karo. App ke SSRF controls, sabse kam permission aur monitoring alag rehte hain.','GuardDuty kuch patterns ke liye InstanceCredentialExfiltration.OutsideAWS likhta hai. Pakadne ki taakat hona yeh saboot nahi ki 2019 ke incident mein kya hota.','Kaam: Decision Dojo ke identity tree mein customer login vs employees/code wali branches compare karo. Advanced appai poora Cognito lab deta hai.'],asli:'Actor aur trust boundary dekh kar identity chuno, phir permission test karo. Sirf signed user token har object/action ki permission nahi deta.'}
    ],
    myth:[{myth:'Rotation purani files dobara likhta hai aur leak hue passwords theek kar deta hai.',sach:'KMS material rotation purani files ko decrypt karne ki taakat bachata hai. Files ka migration aur backend credential ka rotation alag kaam hain.'},{myth:'Bucket Keys bilkul 99% bachat aur har file ka KMS audit dete hain.',sach:'Bachat requester/workload/cache par depend karti hai; cache wala use KMS calls aur unse jude audit events kam karta hai.'},{myth:'WAF Count aur GuardDuty finding ka matlab attack ruk gaya.',sach:'Count sirf dekhta hai; GuardDuty supported signals pakadta hai. Laagu karne wale actions aur nazar wale response ka alag saboot chahiye.'},{myth:'Har public ACM cert free/non-exportable hai; har GuardDuty plan bina agent ka hai.',sach:'ACM certificate ke modes alag hain; optional GuardDuty Runtime Monitoring agent use karta hai. Exact integration/plan dekho.'}],
    playbook:{title:'Risk dekh kar control chuno',use:['Key policy/audit/lifecycle ki zaroorat → customer managed KMS; sirf S3 at-rest ki zaroorat → SSE-S3 chal sakta hai','Backend credential ka lifecycle → Secrets Manager; bina rotation ka config → Parameter Store','HTTP pattern/rate ke signals → WAF; threat ka saboot → GuardDuty + incident owner'],avoid:['Encryption ko permission ya backup ki jagah samajhna','RotationEnabled, detector ENABLED ya ACL association ko runtime protection ka saboot samajhna'],how:['Actor/action/resource aur zaroori saboot pehchano','Rokne/pakadne/jawaab dene ke owners chuno; chhota access aur negative raaste test karo','Sahi runtime mein asli bytes/backend credential/traffic ka result check karo'],redflags:['Wildcard key decrypt, purani key delete, recovery ki koi list nahi','Backend test se pehle secret label promote, logs mein credentials','WAF ka origin bypass, sirf Count wala rollout bhool gaye, findings bina response ke'],rule:'Config → access → asli result: har boundary ka alag saboot.',compare:{heads:['Need','Choose','Trade-off'],rows:[['Simple S3 encryption','SSE-S3','Customer key policy/lifecycle ka control nahi'],['Fine key governance','Customer managed KMS','Kharcha, quotas aur key par tikna'],['Credential rotation','Secrets Manager','Backend/consumer ki recovery phir bhi chahiye'],['Config values','Parameter Store','Credential rotation andar se nahi'],['HTTP attack patterns','WAF','Galat blocks, coverage aur bypass ka review'],['Threat signals','GuardDuty','Coverage aur response ka owner']]},trees:['encryption','secrets','firewall','identity']},
    exam:[{cue:'Envelope encryption',pick:'local data encryption + KMS se lapeti data key'},{cue:'SSE-KMS read',pick:'S3 permission + chalne layak, allowed key'},{cue:'Customer rotation period',pick:'eligible 90–2560 din, fixed saalana nahi'},{cue:'Bucket default',pick:'aage ki files; Bucket Key ki bachat 99% tak, workload par depend'},{cue:'Secrets rotation',pick:'backend set/test aur version promotion, sirf save hua config nahi'},{cue:'CloudFront viewer certificate',pick:'ACM us-east-1'},{cue:'SQLi/rate signals',pick:'WAF; DDoS features → Shield; ek jagah ki policies → Firewall Manager'},{cue:'Threat / vulnerability / PII / compliance',pick:'GuardDuty / Inspector / Macie / Config'},{cue:'Customer login',pick:'Cognito; employees → Identity Center; code → IAM role'}],
    lesson:['<h3>Kab kya: faisle ka naksha</h3><div class="tbl-wrap"><table class="security-table"><tr><th>Dikhi zaroorat</th><th>Option</th><th>Limit</th></tr><tr><td>S3 at-rest ki buniyad</td><td>SSE-S3</td><td>Customer key ka lifecycle nahi</td></tr><tr><td>Key policy/audit ka control</td><td>Customer managed KMS</td><td>Kharcha, quotas aur dependency recovery</td></tr><tr><td>Backend credential rotation</td><td>Secrets Manager</td><td>Backend test aur app refresh zaroori</td></tr><tr><td>Bina rotation ka config</td><td>Parameter Store</td><td>Tier/throughput/KMS review kiye</td></tr><tr><td>HTTP attack ke signals</td><td>WAF</td><td>Galat blocks aur bypass raaste</td></tr><tr><td>Shaq wali activity</td><td>GuardDuty</td><td>Coverage + response owner</td></tr></table></div><p><b>Faisla kaise karein:</b> data padha nahi ja raha? File ki key → key ki state → policy/context dekho. Credential ka lifecycle? Backend rotation chahiye → Secrets Manager; sirf config → Parameter Store. HTTP ka galat use? WAF + app ke controls; AWS mein shaq wali activity → GuardDuty + incident response. Customer login → Cognito; employees ka AWS access → Identity Center.</p>'],
    stages:[
      {type:'dryrun',lesson:'HTTP ka laagu hona, key ki permission aur credential backend ke results: teeno ka alag saboot chahiye. Config ka readback ek boundary hai, poora protection test nahi.',title:'🧪 Login attack aur invoice read alag boundaries',intro:'Course fixture: ek shor machane wala IP, phir bikhre bots; alag se ek invoice read KMS access par fail hota hai. Har step click karo; panel ka text saboot samjhata hai.',nodes:[N('app',150,150,{label:'Client'}),N('waf',460,150,{label:'WAF'}),N('ec2',770,150,{label:'App role'}),N('kms',770,420,{label:'KMS'}),N('s3',460,420,{label:'Invoice'})],edges:[{from:'app',to:'waf'},{from:'waf',to:'ec2'},{from:'ec2',to:'kms'},{from:'kms',to:'s3'}],panels:[{id:'edge',title:'HTTP / protection'},{id:'data',title:'Key / data evidence'}],steps:[
        {say:'Ek source set kiye /login IP rate signal se upar jaata hai. Review kiya Block action WAF ke andaaze aur lagne ke time ke baad matching traffic rok sakta hai.',flows:[{from:'app',to:'waf',label:'login'}],panels:{edge:['IP 100 requests/60 s ki limit lagbhag hai','Count dekhta hai; Block laagu karta hai'],data:['kms:Decrypt ki permission mein koi badlav nahi']}},
        {say:'Botnet koshishein 10,000 IPs mein baant deta hai, har ek set ki per-IP limit ke neeche.',ask:Q('Bikhre, dheeme bot traffic se kya nikalta hai?', 'Per-IP rate control pattern chhod sakta hai; account/bot signals jodo aur sahi users ka review karo',['Har request block hoti hai, kyunki ek IP ki rate limit saare AWS accounts par milakar lagti hai','KMS rotation jaldi karne se bots ruk jaate hain, kyunki encryption login requests ginta hai','WAF metrics band karne se credential stuffing rukti hai, kyunki attackers graph nahi dekh paate'],0,'Ginti set ki gayi key ke hisaab se hoti hai, isliye bikhre bots per-IP rule se bach sakte hain. Account/MFA/bot controls WAF ke saath kaam aate hain; KMS rotation aur metrics dikhna login ki pehchaan nahi karte.'),panels:{edge:['Account signals, bot controls aur shared NAT ke galat blocks review karo'],data:['Detection aur response ka owner alag rehte hain']}},
        {say:'App ek SSE-KMS invoice padhti hai. S3 permission allowed hai, par chuni KMS key disabled hai. Plaintext padhna prove nahi hua.',flows:[{from:'ec2',to:'kms',label:'decrypt',tone:'bad'}],panels:{edge:['WAF config ne key ke use ki permission nahi di'],data:['DisabledException','Permissions/context se pehle key ki state dekho']},ask:Q('Kaunsa repair asli encrypted invoice bachata hai?', 'Asli key review karke dobara on karo, phir allowed principal aur exact encryption context check karo',['Same description wali ek aur key banao, kyunki same naam purana key material bana deta hai','Invoice ko khaali file se badal do, kyunki zero bytes prove karte hain ki encryption chal raha hai','Bucket public kar do, kyunki public S3 policy har KMS key state ko override kar deti hai'],1,'Asli ciphertext asli key material par tika hai. Nayi key purana blob decrypt nahi kar sakti; badalne se data kho jaata hai; public bucket KMS ko override nahi karta. On karne ke baad bhi asli access/context check karna hai.' )},
        {say:'Envelope encryption ek chhoti data key ko secret na hone wale tenant context se kholta hai. Payload ka asli check/decrypt local mein hota hai.',flows:[{from:'kms',to:'s3',label:'unwrap',tone:'ok'}],panels:{data:['Exact context aur chalne layak allowed key','Host par AES-GCM tamper check lab19 mein hai']}},
        {say:'Naya secret version AWSPENDING hai, jabki backend abhi bhi purana password maanta hai. Sirf label backend nahi badalta.',panels:{edge:['Review kiya rotation poora hone tak app current credential use karti hai'],data:['Backend set karo → pending credential test karo → current promote karo']},ask:Q('Pending credential ko promote karna kab sahi hai?', 'Jab sahi backend naya credential maan le aur recovery/client refresh review ho chuka ho',['Jaise hi PutSecretValue VersionId lautaye, kyunki backend passwords apne aap badal jaate hain','GuardDuty detector on karne ke baad, kyunki detector ka status database login check karta hai','Backend test karne se pehle, kyunki current label database ko password maanne par majboor karta hai'],2,'Rotation workflow backend aur secret ko saath chalata hai, phir promote se pehle check karta hai. PutSecretValue sirf data save karta hai; GuardDuty DB ka login nahi karta; labels backend ka password nahi badal sakte.')},
        {say:'Aaj ka association/key/secret state padho. Config runtime check ke liye ready hai; local mein na bot block, na Lambda rotation, na asli threat finding ka daava.',panels:{edge:['WAF association/config ka metadata check hua','Runtime traffic test alag rehta hai'],data:['Host par asli crypto + stage kiya TEST credential reference','Moto ki kamiyan likhi; cleanup check hua']}}
      ]},
      {type:'flowlab',title:'🎛️ KMS requests ka kharcha: bataya hua reuse scenario',goal:'Kam se kam 30 lakh files/mahina aur har file ke 2 reads rakho. Bataye reuse scenario ke liye Bucket Keys on karo, jisse model mein KMS requests ≥80% kam hon aur KMS ka kul kharcha ≤$20/mahina rahe. Shuru: 90% reuse chuno aur Bucket Keys on karo.',scenario:'Lagbhag US East ka kul model: bina reuse har write/read par ek KMS call, $0.03 har 10,000 eligible symmetric calls. Ek customer key $1/mahina + pehle do rakhe gaye material rotations $1 har ek. Reuse % ek maana hua naapa input hai, AWS ka andaaza ya pakka 99% nahi. Asli requester/cache/operations bachat tay karte hain. S3, logging, transfer, tax, allowances aur baaki crypto APIs bahar.',knobs:[{id:'objects',label:'Objects written / month',min:1,max:5,step:1,value:5,fmt:v=>v+' million'},{id:'reads',label:'Reads per object',min:1,max:5,step:1,value:3,fmt:v=>v+' reads/object'},{id:'reuse',label:'Bucket Key ke saath bataya request ka ghatna',min:0,max:3,step:1,value:0,labels:{0:'0%',1:'50%',2:'90%',3:'99%'}},{id:'bucket',label:'Bucket Key enabled',min:0,max:1,step:1,value:0,labels:{0:'Off',1:'On'}},{id:'rotations',label:'Billable retained rotations',min:0,max:2,step:1,value:0,fmt:v=>v+' rotations'}],model:k=>{const c=cost(k),ok=k.objects>=3&&k.reads>=2&&k.bucket===1&&c.calls<=.2*c.baseline&&c.after<=20;return {readouts:[{label:'Baseline KMS calls',value:c.baseline.toLocaleString('en-US')+' calls/month'},{label:'Chune model ke KMS calls',value:c.calls.toLocaleString('en-US')+' calls/month'},{label:'Key/material ka kul kharcha',value:'$'+c.key.toFixed(2)+'/month'},{label:'Baseline KMS gross',value:'$'+c.before.toFixed(2)+'/month'},{label:'Selected KMS gross',value:'$'+c.after.toFixed(2)+'/month'}],verdict:{ok,text:ok?'Bataya workload aur budget is maane hue reuse scenario mein fit hain. Asli bachat aur audit coverage naapo.':'Zaroori workload rakho, phir Bucket Key on karo aur kaafi reuse chuno; budget compare karo.'}};},check:k=>{const c=cost(k);return k.objects>=3&&k.reads>=2&&k.bucket===1&&c.calls<=.2*c.baseline&&c.after<=20;},lesson:'Default workload 2 crore calls/mahina = KMS ka kul kharcha lagbhag $61; maana hua 90% ghatna 20 lakh calls aur lagbhag $7 deta hai. Cache wali Bucket Key requests ko KMS call nahi karna padta, isliye file level audit ke liye S3 data events chahiye ho sakte hain. Yeh model caching ya turant key cancel hona nahi naapta.'},
      {type:'bins',title:'Rokna, pakadna ya mil kar recovery?',instructions:'Service ka mukhya kaam chuno. Mile-jule systems mein kaam overlap ho sakte hain; labels bataye gaye action ko dikhate hain.',bins:[{id:'prevent',label:'Prevent / restrict'},{id:'detect',label:'Detect / evidence'},{id:'recover',label:'Coordinate recovery'}],items:[{text:'Asli HTTP entry point par WAF ka review kiya Block rule',bin:'prevent',explain:'Matching requests ko roka ja sakta hai; Count sirf dekhta.'},{text:'Ek tenant context ke liye KMS ki chhoti decrypt policy',bin:'prevent',explain:'Key ki permission plaintext tak pahunch rokti hai; context secret nahi, check hone wala metadata hai.'},{text:'Saunpe gaye incident owner ke saath GuardDuty finding',bin:'detect',explain:'Finding threat ka signal hai; rokna/check karna alag kaam hai.'},{text:'Macie chuni S3 files mein sensitive values dhoondhta hai',bin:'detect',explain:'Dhoondhna/label lagana un values ko chhupata ya delete nahi karta.'},{text:'Secret rotation backend set/test karta hai, phir current promote',bin:'recover',explain:'Credential ka lifecycle backend, versions aur client refresh ko saath chalata hai.'},{text:'CloudTrail ke chune management/data events review hue',bin:'detect',explain:'Audit scope mein sahi actions hone chahiye; yeh apne aap rokta nahi.'}]},
      {type:'triage',title:'🩺 GetObject allowed, par KMS access denied',symptom:'TRAINING app role ke paas s3:GetObject aur IAM kms:Decrypt hai. Asli invoice key Enabled hai; par uski key policy mein app ke liye seedha Allow ya account delegation nahi hai.',goal:'Access chauda karne se pehle asli permission boundary pehchano.',commands:[{cmd:'aws s3api head-object --bucket shop-invoices --key invoice101',out:'ServerSideEncryption: aws:kms\nSSEKMSKeyId: invoice-archive-key',clue:false,note:'Purani file ki key maayne rakhti hai; bucket default badalne se file dobara nahi likhi jaati.'},{cmd:'aws kms describe-key --key-id invoice-archive-key',out:'KeyState: Enabled',clue:false,note:'Key ki state chalne layak hai; ab permission dekho.'},{cmd:'aws kms get-key-policy --key-id invoice-archive-key --policy-name default',out:'TRAINING policy sirf management allow karti hai; app ke liye kms:Decrypt ka Allow ya account delegation nahi',clue:true,note:'Sirf IAM Allow woh permission nahi jod sakta jo key policy chalu nahi karti.'}],questions:[Q('Is khaas read failure ki wajah kya hai?', 'On key ki policy mein app ke decrypt ke liye koi lagu raasta nahi hai; sirf IAM Allow kaafi nahi',['Bucket default SSE-KMS use karta hai, isliye har purani file apne aap doosri key par chali gayi','WAF rate rule /login tak hai, isliye invoice ke KMS decrypt calls login traffic mein gine jaate hain','Secret ka 30 din ka rotation schedule hai, isliye rotations ke beech KMS decrypt apne aap deny hota hai'],3,'S3 aur key ka use alag checks hain; key policy ko sahi raasta chalu karna chahiye. Defaults purani files migrate nahi karte, WAF KMS ki permission nahi deta, aur secret ka schedule key access tay nahi karta.'),Q('Is key-policy fixture ke liye kaunsa repair sahi hai?', 'Review kiya chhota decrypt principal/context raasta jodo, administration rakho, phir asli file test karo',['Principal:* ko kms:* do aur purani key hata do, kyunki encryption ke baad access scope ki zaroorat nahi','Block Public Access band karo, kyunki public file ko KMS permission ka raasta nahi chahiye','Doosri key banao aur sirf bucket default badlo, kyunki purana invoice padhte waqt dobara encrypt hota hai'],0,'Chhota raasta + bachaya admin/recovery is fixture mein fit hai. Wildcard grants access chauda karte hain aur delete karne se data kho sakta hai; public access KMS ko bypass nahi karta; default badalne se purane bytes dobara encrypt nahi hote.') ]},
      {type:'terminal',title:'🖥️ Protection ka config theek karo, aaj ke saboot ke saath',instructions:'ls/cat taiyaar JSON dikhate hain. Saare commands app ke fixtures hain; koi AWS call nahi. Rotation aur WAF checks sirf save hua config prove karte hain.',goal:'<p><b>1.</b> key-policy.json ke saath customer symmetric key banao; pehli nayi KeyId expected hai: '+ID+'. Alias alias/shop-invoices; 180 din ka rotation on karo. Purani archive key/invoices bachao.</p><p><b>2.</b> shop-invoices par encryption.json lagao. Purani file AES256 hi rehni chahiye. secret.json se TEST secret shop/db nayi key ke saath save karo. db-secret-rotator/rotation.json ko --no-rotate-immediately ke saath set karo; phir aaj ka secret padho. Fixture rotation ka config save karta hai; AWS phir bhi testSecret chalata hai aur asli runtime check nahi hua.</p><p><b>3.</b> /shop/payment-token ko SecureString ke roop mein nayi key aur TEST_ONLY_api_token ke saath put karo; decryption ke saath GetParameter. Secret/token course ka temporary data hai.</p><p><b>4.</b> Regional shop-login ACL banao: default Allow, waf-rules.json aur visibility.json. Pehla ACL Id expected hai: '+ACLID+'. Isse bilkul asli shop-alb ARN se jodo, phir poore output ke saath GetWebACLForResource chalao. Review kiye rules aur asli association dikhne chahiye. Koi HTTP traffic nahi chalta.</p><p>Asli IDs/data/function rakho. Missing key/policy/context, sirf Count wala ACL, galat target, delete hua data ya purane reads se jeet nahi milegi. Hints ke commands dheere-dheere aage badhte hain; solution mein 12 actions hain.</p>',account:seed(),files,tasks,solution:mainSolution,hints:['Pehle taiyaar policy/encryption/rotation/rules files dekho. Key management, secret ka config aur WAF association alag checks hain.',mainSolution.slice(0,4).join(' phir '),mainSolution.slice(4,9).join(' phir '),mainSolution.slice(9).join(' phir ')],success:AG.allOf(tasks),successText:'Purane invoices bache. Nayi key/defaults aur padhe ja sakne wale TEST credentials review ki state mein fit hain; rotation config save hai aur asli ALB par review kiya aaj ka ACL association hai. Asli rotation, WAF ka traffic par laagu hona aur threat detection alag runtime tests hain.'},
      {type:'docker',title:'🐳 Lab19: asli envelope crypto aur control-plane ki kamiyan',project:'19-kms-secrets-waf',goal:'Apne server wala lab chalao, host ke asli crypto ko metadata se compare karo, aur cleanup check karo.',why:'Disabled key ka decrypt, secret stage/default reads aur unsupported finding APIs Moto ki kamiyan dikhate hain. Emulator ka safal jawaab production protection ka saboot nahi.',steps:[{text:'README/lab.py padho, phir pehle bane local environment ke saath chalao.',cmd:'source ../env.sh && ../.venv/bin/python -I lab.py',expect:'14 behaviour checks + cleanup = 15. 7,000-byte AES-GCM roundtrip aur tamper failure; KMS wrapping aur S3 defaults local Moto operations hain.'},{text:'Stage promotion ke baad saaf AWSCURRENT aur default secret compare karo; rotation/GuardDuty ki kamiyon wali lines padho.',expect:'Moto ka default purana reh sakta hai; disabled KMS decrypt maan liya jaata hai; rotation period chhoot jaata hai; bina Lambda ke rotation galat taur par set dikhta hai; GuardDuty finding endpoints 404. Asli DB/Lambda rotation ya HTTP inspection nahi.'},{text:'Apne resources ka cleanup aur listener band hona check karo.',expect:'PASS 15: apne resources hate; KMS key 7 din mein delete ke liye scheduled. OWNED MOTO STOPPED / LISTENER CLOSED. Sirf apna temporary server.'}],observe:Q('Lab19 sach mein kis result ko support karti hai?', 'Host par AES-GCM check aur local metadata/stage operations pass hue; runtime protection check nahi hui',['Har KMS denial aur WAF bot block AWS se match hua, kyunki local HTTP jawaab ka status safal tha','Lambda ne asli PostgreSQL password rotate kiya, kyunki secret ne bina function ke RotationEnabled dikhaya','GuardDuty ne chalu mining traffic pakda, kyunki detector banane se apne aap asli incident ban gaya'],1,'Host ka asli crypto aur supported metadata operations pass hue; pakdi gayi emulator ki kamiyan bade daavon ko rokti hain. Koi WAF HTTP engine, DB/Lambda runtime ya asli GuardDuty finding nahi chali.')},
      {type:'quiz',title:'🎓 Security decision review',questions:[
        Q('Naye customer objects ko basic at-rest encryption chahiye, customer key policy ki zaroorat nahi. Sabse kam chalane ki mehnat?', 'SSE-S3 default encryption, IAM/bucket access controls aur zaroori audit scope review karke',['Har file ke liye customer managed SSE-KMS, kyunki SSE-S3 bina manual keys ke data encrypt nahi kar sakta','CloudHSM dedicated clusters, kyunki basic at-rest zaroorat ko hamesha single-tenant hardware chahiye','Har client ke liye client-side encryption, kyunki server-side encryption at-rest protection poori nahi kar sakta'],0,'SSE-S3 is bataye requirement ko customer key lifecycle ke bina poora kar sakta hai. KMS governance jod sakta hai par har jagah zaroori nahi; CloudHSM ko dedicated key ki zaroorat chahiye; client-side se plaintext kahan khulta hai aur operations badal jaate hain.'),
        Q('Ek 7,000-byte document ko check hone wali client-side encryption chahiye, KMS ki wrapping key ke saath. Kya chunoge?', 'Data key banao, check hone wale format se local mein encrypt karo, ciphertext aur wrapped key save karo',['Poora document symmetric KMS Encrypt ko bhejo, kyunki ciphertext output ki koi size limit nahi','Plaintext data key encrypted document ke bagal mein rakho, kyunki KMS key alias bytes chhupa deta hai','Tenant ka password EncryptionContext mein daalo, kyunki context encrypt hota hai aur audit logs mein nahi dikhta'],1,'Seedhe symmetric Encrypt ki plaintext limit 4096 bytes hai. Bade payload ke liye envelope encryption; plaintext key ko sahi se bachana/hatana hai; context secret nahi, check hone wala metadata hai, password rakhne ki jagah nahi.'),
        Q('Ek eligible customer symmetric AWS_KMS key ko 180 din ka automatic material rotation chahiye. Sahi ummeed kya hai?', '180 din ka rotation on karo; key ID aur purana decrypt material rehta hai, data migration chahiye toh alag',['Har 180 din nayi key banao aur purani turant delete karo, taaki asli ciphertext padha ja sake','Automatic rotation on karo, kyunki har customer key saal mein rotate hoti hai aur gap badla nahi ja sakta','Rotation on karo taaki agli safal GetObject par saari purani S3 files nayi key ID se dobara likhi jaayein'],2,'Eligible gap 90–2560 din set ho sakta hai; rotation pehchaan aur purana material bachata hai. Purani keys delete karne se data kho sakta hai; customer rotation khud on karna padta hai; material rotation S3 files dobara nahi likhta, na DB credentials rotate karta hai.'),
        Q('Bucket Keys on hain aur bahut saare reads cache ka material dobara use karte hain. Kaunsi audit/kharche ki baat sahi hai?', 'KMS calls kaafi gir sakti hain; requesters/reuse naapo aur sahi S3 object-event auditing lagao',['Har file GET ab bhi ek KMS Decrypt audit event banata hai, isliye KMS logs mein saare file accesses hain','Har workload bilkul 99 percent bachata hai, kyunki requesters ki ginti aur access pattern caching par asar nahi daalte','Purani encrypted files ko turant Bucket Keys mil jaati hain, kyunki default config data migrate kar deta hai'],3,'99% tak workload par depend hai. Cache wala Bucket Key use har request par KMS call/key policy check nahi karta; file ke audit ke liye chune S3 data events chahiye. Default ka badlav aage ki writes par lagta hai, purani files apne aap migrate nahi hoti.'),
        Q('Naya AWSPENDING password hai, par DB purana credential maanta hai. Production mein agla safe kadam?', 'Sahi backend credential set aur check karo, recovery/client refresh plan karo, phir current promote karo',['Turant AWSCURRENT promote karo, kyunki secret label hilane se database ka password apne aap badal jaata hai','KMS material rotation schedule karo, kyunki wrapping key badalne se database mein credentials update hote hain','Macie scan on karo, kyunki sensitive data pehchanne se pending password login ke layak ban jaata hai'],0,'Save hua secret aur backend credential alag hain. Rotation set/test, phir promotion/recovery ko saath chalata hai; labels DB nahi badalte; KMS material rotation password nahi badalta; Macie data ko label karta hai.'),
        Q('/login ka per-IP WAF rate rule lagbhag 100 requests/60 s par block karta hai. 10,000 IPs har ek thodi requests karte hain. Ab kya?', 'Bikhre account/bot signals, galat blocks aur app ke controls review karo; sirf per-IP rate ka galat use chhoot sakta hai',['100 ko exact global account quota maano, kyunki WAF har bikhre IP ko ek hi source ginta hai','Kisi aur, na jude ACL par Count ko Block karo, kyunki association ka laagu hone par koi asar nahi','App ki parameterized queries band karo, kyunki WAF managed rules server ki query safety ki jagah le lete hain'],1,'Set ki gayi ginti ki keys maayne rakhti hain; bikhre sources per-IP limits se bach sakte hain. WAF andaaza lagata hai, exact quota nahi; asli entry resource se jodna zaroori hai; app ke query/login controls phir bhi chahiye.'),
        Q('Zaroorat: app mein customer sign-in, aur employees ko kai AWS accounts ka access. Kaunsi jodi?', 'App customers ke liye Cognito aur employees ke AWS access ke liye IAM Identity Center, scoped permission ke saath',['Saare customers ke liye IAM users aur employees ke liye ek shared root login, kyunki dono AWS access dete hain','Sirf Cognito identity-pool ke temporary credentials ko saboot maano ki har user har tenant ki file padh sakta hai','Customer sessions ke liye Secrets Manager mein password aur employees ki federation ke liye CloudHSM clusters'],2,'Actors aur trust boundaries alag hain. Cognito app ki pehchaan sambhalta hai; Identity Center employees ki; token/credentials ko phir bhi permission chahiye. IAM/root share karna aur alag secret/HSM tools in zarooraton ko poora nahi karte.'),
        Q('Ek covered workload par GuardDuty credential chori hone ka shaq batata hai. Yeh finding kya pakka karti hai?', 'Threat ka signal, jiske liye incident owner ko jaanch, scoped rokna aur recovery ka check chahiye',['Saare chori hue credentials ka pakka automatic block, kyunki har GuardDuty plan API calls rokta hai','Guarantee ki har workload ka runtime coverage hai, kyunki basic analysis koi optional agent use nahi karta','Poora incident response, kyunki Security Hub ki ginti har asar wali key ko apne aap rotate kar deti hai'],3,'Finding ek signal hai, pakka block ya theek hona nahi. Coverage/plans alag hain; Runtime Monitoring agent use karta hai; ginti credentials apne aap rotate nahi karti. Saboot bachao aur scoped response check karo.')
      ]}
    ],
    interview:{title:'Interview: asli ciphertext aur key ki recovery',instructions:'Boundary samjhao, phir asli band TEST invoice theek karo. Commands state/access/context ka model hain; asli envelope crypto lab19 mein hai.',questions:[
      Q('S3:GetObject aur IAM kms:Decrypt allowed hain, par key policy mein decrypt ka koi raasta nahi. Sabse sahi pehchaan?', 'Key policy ko sahi access raasta chalu karna chahiye; sirf IAM Allow woh permission nahi bana sakta',['S3 file ko public karna padega, kyunki public object policy har key policy ki shart ko override karti hai','File ko nayi key ke saath badal do, kyunki aaj ka default badalna purana ciphertext bachata hai','API ko bina ruke retry karna chahiye, kyunki missing key-policy permission thodi der ki network dikkat hai'],0,'Key policy lagu raaste control karti hai; default delegation/seedha Allow/grants alag hain. Public bucket KMS override nahi karta; file badalna data badalta hai; baar-baar ka pakka AccessDenied config ki jaanch maangta hai.'),
      Q('Operator Lambda wale secret ka schedule badalte waqt --no-rotate-immediately use karta hai. Kya hoga?', 'AWS phir bhi testSecret chalata hai; sirf save hua schedule backend password ke safal badalne ka saboot nahi',['AWS koi Lambda invocation nahi hone ki guarantee deta hai, kyunki flag saare tests aur aage ke rotations band kar deta hai','AWS bana hua current password promote karta hai, chahe backend se connection ya rotation permission na ho','AWS KMS wrapping key rotate karta hai, aur isliye us customer key wale har database ka password update hota hai'],1,'RotateImmediately=false hone par bhi Lambda config testSecret se test hota hai. Yeh bina invocation ka vaada nahi, backend ki safalta alag hai, aur KMS rotation database credentials ki jagah nahi leta.'),
      Q('WAF update par WAFOptimisticLockException aata hai. Kaunsi recovery saath mein review hua config bachati hai?', 'Aaj ka ACL/token lo, badlav review karo, phir naye token ke saath poora sahi config lagao',['Wahi token baar-baar use karo, kyunki optimistic lock errors prove karte hain ki kisi aur ne ACL nahi badla','Asli ALB delete karke dobara banao, kyunki association ka metadata web ACL ka lock token control karta hai','Rate rule hatao aur default Allow karo, kyunki simple rule set purane tokens ko valid bana deta hai'],2,'Naya read/review/update optimistic concurrency mein fit hai; aankh band retries purani state dobara use karte hain, ALB dobara banane se scope kho jaata hai, aur config simple karna purane token ko valid nahi banata.'),
      Q('Capital One 2019 defense ke review ki wajah deta hai. Kaunsi baat jo saboot hai uske andar rehti hai?', 'App/metadata aur role ki boundaries review karo; likhi hui detection ki taakat rokne ka saboot nahi',['GuardDuty pakka band tha, aur detector on karne se har bataya gaya data access ruk jaata','Encryption guarantee deta hai ki chori hue IAM roles data nahi padh sakte, chahe unke paas decrypt permission ho','Koi bhi managed WAF rule group lagana prove karta hai ki asli incident chain kisi aur app mein kabhi dobara nahi hogi'],3,'DOJ galat set kiye web application firewall ka zikr karta hai aur Capital One asar wale logon ki ginti batata hai. Lesson detector ki state ya "aisa hota toh ruk jaata" saabit nahi karta; allowed chori hue roles aur doosre bypass phir bhi ho sakte hain.'),
      {terminal:{type:'terminal',title:'🖥️ Asli key/context ke saath read wapas laao',instructions:'Allowed training reviewer asli key theek karta hai. Scope sirf key ki state, review ki policy aur crypto use ke access ka model hai; poora management-IAM evaluator nahi.',goal:'<p>Asli invoice-archive-key Disabled hai, aur review kiya decrypt access missing hai. <b>1.</b> Dependency review ke baad asli key on karo. <b>2.</b> policy-name default ke saath key-policy.json lagao, administration aur tenant tak scoped reviewer decrypt bachate hue. <b>3.</b> Asli fileb://invoice-cipher.bin ko exact tenant shopkaro/purpose invoice context ke saath decrypt karo. Base64 Plaintext aana chahiye jo TEST invoice101 INR2500 dikhaye.</p><p>Nayi key, badla context, chaudi policy, delete hua invoice ya purana readback nahi chalega. App ka blob ek band TEST handle hai; asli cryptography ya customer data nahi.</p>',account:seed(true),files,tasks:itasks,solution:interviewSolution,hints:['describe-key aur get-key-policy dekho; asli ciphertext asli key aur matching context par tika hai.',interviewSolution.slice(0,2).join(' phir '),interviewSolution[2]],success:AG.allOf(itasks),successText:'Asli TEST ciphertext asli on key, review ki tenant policy aur exact context ke saath padha gaya. Badalne/data delete karne ka shortcut nahi, aur asli HSM/cryptography ka daava nahi.'}}
    ]},
    success:['Risk ko rokne/pakadne/jawaab dene ki boundaries mein baant sakta hoon','KMS key ki state/policy/context aur rotation ki limits debug kar sakta hoon','Credential versions aur backend/runtime ke saboot ka farak samjha sakta hoon','WAF/GuardDuty ka config aur naape gaye results alag pehchaan sakta hoon'],
    homework:'<p><b>Optional, sirf approved AWS sandbox mein (paisa lagega).</b> Pehle aaj ke Region/quotas/daam aur budget dekho. Sirf apni nakli key/secret/parameters, scoped policy aur test data banao. KMS ka positive/negative access/context aur asli encryption check karo. Approved TEST backend/handler aur client refresh ke saath secret rotation test karo; promotion se pehle failures dekho. WAF ke liye apna supported entry resource use karo, pehle Count/canary review, phir sahi laagu karna; sahi aur attack requests ke asli results pakdo. Chune GuardDuty plans/coverage set karo aur bina galat traffic ke sample findings dekho. Asli credentials kabhi log mat karo, customer endpoints par test mat karo. Cleanup: apne associations/ACL, parameters/secrets, data/compute/functions/roles/logs; dependency review ke baad apni KMS key ka delete schedule karo aur waiting period/baaki chalu kharcha dekho. Service ke recovery niyam follow karo; shared resources par protection band mat karo.</p>',
    cards:[{front:'Encryption replaces IAM?',back:'Nahi. At-rest encryption, plaintext access ki permission aur backup/recovery ke kaam alag hain.'},{front:'Seedha KMS se bada payload?',back:'Symmetric Encrypt plaintext ≤4096 bytes; envelope encryption data key ko lapet-ta hai aur payload ko local mein encrypt/check karta hai.'},{front:'Customer key rotation?',back:'Eligible AWS_KMS symmetric automatic rotation khud on karna padta hai, 90–2560 din; pehchaan/purana decrypt material bacha rehta hai. Files ya passwords apne aap dobara nahi likhe jaate.'},{front:'Bucket Keys ka audit wala jaal?',back:'99% tak ki bachat workload par depend hai; cache wale reads KMS calls/policy check chhod sakte hain. File access ke saboot ke liye S3 data events chuno.'},{front:'RotationEnabled means rotated?',back:'Sirf config. Backend set/test aur credential/client recovery ko runtime saboot chahiye; no-immediate flag ke saath bhi testSecret chalta hai.'},{front:'WAF rate ki limit exact hai?',back:'Nahi; 60/120/300/600 s mein andaazan ginti, lagne ka time, aur bikhre/shared IP ki shartein. Count dekhta hai, review kiya Block laagu karta hai.'},{front:'GuardDuty agentless?',back:'Basic analysis optional Runtime Monitoring se alag hai, jo agent use karta hai. Coverage/finding/response alag rehte hain.'},{front:'Lab19 actual proof?',back:'Host par AES-GCM roundtrip/tamper + local control-plane/stage operations. Moto ki disabled-key/default-secret/finding wali kamiyan; asli DB/Lambda/WAF/GuardDuty runtime nahi.'}]
  }]);
})();
